mapper.update:
update biz_stock
set qty_available = qty_available - #{qty},
    qty_locked = qty_locked + #{qty}
where stock_id = #{stockId} and qty_available >= #{qty}

update biz_stock
set qty_available = qty_available + #{qty},
    qty_locked = qty_locked - #{qty}
where stock_id = #{stockId} and qty_locked >= #{qty}

mapper.select:
select count(*) from biz_order o
where o.store_id = 1 and o.member_id = #{memberId}
and o.status = #{status}
